students = {
    "An":   [8, 9, 7],
    "Binh": [6, 5, 7],
    "Chi":  [10, 9, 10],
}

def average(scores):
    return sum(scores) / len(scores)

def letter(avg):
    if avg >= 9:
        return "A"
    elif avg >= 8:
        return "B"
    elif avg >= 6.5:
        return "C"
    return "D"

for name, scores in students.items():
    avg = average(scores)
    print(f"{name:<6} {avg:5.2f}  {letter(avg)}")

